:- module(test_arith, [test_arith/0]).
:- use_module(library(plunit)).
:- use_module(library(debug)).

/** <module> Test Prolog core arithmetic functions

@author	Jan Wielemaker
*/

test_arith :-
	run_tests([ arith_basics,
		    div,
		    gdiv,
		    rem,
		    mod,
		    pow,
		    gcd,
		    shift,
		    errors,
		    ar_builtin,
		    eval,
		    hyperbolic,
		    bigint,
                    minint,
                    minint_promotion,
                    maxint,
                    maxint_promotion,
		    round,
		    float_misc,
		    float_overflow,
		    float_zero,
		    float_special,
		    float_compare,
		    arith_misc,
		    max_integer_size,
		    moded_int
		  ]).

:- begin_tests(arith_basics).

test(arith_1, A == 10) :-
    A is 5 + 5.
test(arith_2) :-
    0 =:= -5 + 2.5 * 2.
test(arith_3, B =:= -1) :-
    A is pi,
    B is cos(A).
test(arith_4) :-
    0 =:= 10 - 3.4 - 6.6.
test(arith_5) :-
    1 =:= integer(0.5).
test(arith_6) :-
    4.5 =:= abs(-4.5),
    4 =:= abs(4),
    4 =:= abs(-4).
test(arith_7) :-
    5.5 =:= max(1, 5.5).
test(arith_8) :-
    -6 is min(-6, -5.5).
test(arith_9) :-
    4000 =:= integer(10000 * float_fractional_part(1.0e10 + 0.4)).
test(arith_10) :-
    -4000 =:= integer(10000 * float_fractional_part(-1.0e10 - 0.4)).
test(float_fractional_part_1) :-
    0 is float_fractional_part(4).
test(arith_11) :-
    1.0 is sin(pi/2),
    \+ 1 is sin(pi/2).
test(arith_12) :-
    1.0 is float(sin(pi/2)).
test(arith_13) :-
    1.0 =:= sin(pi/2).
test(sign_1) :-
    -1   is sign(-1),   0   is sign(0),   1   is sign(1).
test(sign_2) :-
    -1.0 is sign(-1.5), 0.0 is sign(0.0), 1.0 is sign(pi).
test(sign_3) :-
    0.0 is sign(-0.0).
test(copysign_1) :-
    -1 is copysign(1, -0.0),
     1 is copysign(1, 0.0).
test(copysign_2) :-
    -2.0 is copysign(2.0, -0.0),
    2.0 is copysign(2.0, 0.0).
test(copysign_3) :-
    1  is copysign(1, 1),
    -1 is copysign(1, -1).
test(abs_1, A == 0.0) :-
    A is abs(-0.0).
test(floor_1) :-
    0 is floor(0.0),
    0 is floor(0.9),
    -1 is floor(-0.1),
    -1 is floor(-0.9).
test(ceil_1) :-
