    pi > 5 rdiv 2.
test(clause_1) :-
    Clause = (gmp_clause(X,Y) :-
                   X is Y + 3353461138769748319272960000),
    assert(Clause, Ref),
    clause(H,B,Ref),
    erase(Ref),
    (H:-B) =@= Clause.
test(comp_1) :-
    retractall(gmp_clause(_,_)),
    forall(between(1, 50, X),
           (   oefac(X, Fac),
               assert(gmp_clause(Fac, X))
           )),
    forall(between(1, 50, X),
           (   oefac(X, Fac),
               gmp_clause(Fac, Y),
               X == Y,
