:- module(test_fastrw, [test_fastrw/0]).
:- use_module(library(plunit)).
:- use_module(library(debug)).

/** <module> Test fast term I/O

This module is a Unit test  for   Prolog  built-ins for fast binary term
serialization

@author	Jan Wielemaker
*/

test_fastrw :-
	run_tests([ fastrw
		  ]).

term(int, 0).
term(int, -1).
term(int, 1).
term(int, X) :- X is 1<<62.
term(float, 0.0).
term(float, X) :- X is pi.
term(atom, '').
term(atom, aap).
term(atom, noot).
term(atom, A) :-
	numlist(1, 1100, L),
	atom_codes(A, L).
term(string, S) :-
	term(atom, A),
	atom_string(A, S).
term(nil, []).
term(compound, f(1)).
term(compound, f(1, f(2))).
term(cyclic, X) :- X = f(X).
term(list, L) :-
	numlist(-1000, 1000, L).

:- begin_tests(fastrw, [sto(rational_trees)]).

test(serialize) :-
	forall(term(_, T),
	       ( fast_term_serialized(T, S),
		 fast_term_serialized(T2, S),
		 assertion(T =@= T2))).
test(fastrw) :-
	findall(T, term(_,T), L),
	setup_call_cleanup(
	    tmp_file_stream(binary, File, Out),
	    maplist(fast_write(Out), L),
	    close(Out)),
	setup_call_cleanup(
	    open(File, read, In, [type(binary)]),
	    maplist(read_and_check(In), L),
	    close(In)),
	delete_file(File).

read_and_check(In, T) :-
	fast_read(In, T2),
	assertion(T =@= T2).

test(error, error(permission_error(fast_serialize, blob, S))) :-
	setup_call_cleanup(
	    ( open_null_stream(S),
	      set_stream(S, encoding(octet))
	    ),
	    fast_write(S, a(X,X,S)),
	    close(S)).

:- end_tests(fastrw).
