:- module(test_meta_predicate, [test_meta_predicate/0]).
:- use_module(library(plunit)).
:- use_module(library(debug)).

/** <module> Test meta predicate handling

@author	Jan Wielemaker
*/

test_meta_predicate :-
	run_tests([ meta_predicate
		  ]).

:- meta_predicate
	m(:, -),
	m(:, +, -),
	m2(+, :, -).

m(In, Out) :-
	Out = In.
m(_, X, X).
m2(X, _, X).

:- begin_tests(meta_predicate).

:- dynamic this/1.
:- (   this(_)
   ->  true
   ;   prolog_load_context(module, M),
       assert(this(M))
   ).

a(_).

mtry:no :- fail.

mdepart(_) :-
	mtry:no, !.
mdepart(X) :-
	context_module(X).

% What a variable is qualified, a term is pushed onto the global stack
% and the frame argument becomes a reference pointer to a var in this
% term.  This should be trailed.  Backtracking should also maintain the
% qualification.

:- meta_predicate mq(:).

mq(T) :-
    assertion(functor(T, :, 2)),
    fail.
mq(T) :-
    assertion(functor(T, :, 2)),
    fail.

tbacktrack :-
    tbacktrack(X),
    term(T),
    term(T),
    assertion(var(X)).

tbacktrack(V) :-
    mq(V).
tbacktrack(V) :-
    assertion(var(V)).

term(t(42)).

		 /*******************************
		 *	       TESTS		*
		 *******************************/

test(qualify, X == M:x) :-
	this(M),
	m(x, X).
test(qualify, X == m1:x) :-
	m(m1:x, X).
test(qualify, X == m1:Y) :-
	a(Y),
	m(m1:Y, X).
test(qualify, X == m1:Y) :-
	a(Y), freeze(Y, fail),
	m(m1:Y, X).
test(qualify, X == m1:x) :-
	m(m2:m1:x, X).
test(qualify, X == 42:x) :-		% do not check module-type
	m(m2:42:x, X).
test(alias, X == Out) :-		% shared variables
	m(X, X, Out).
test(alias2, X == Out) :-		% shared variables
	m2(X, X, Out).
test(i_departm, X == Me) :-
	context_module(Me),
	mdepart(X).
test(backtrack) :-
	tbacktrack.

:- end_tests(meta_predicate).
