         current_prolog_flag(signals, true),
         current_prolog_flag(threads, true)
       )).
:- use_module(library(unix)).

test_signals :-
    run_tests([ signals
              ]).

:- begin_tests(signals).

:- dynamic done/0.

test(sync) :-
    retractall(done),
    setup_call_cleanup(
        on_signal(term, Old, term),
        test_term,
        on_signal(term, _, Old)).

term(_Sig) :-
    length(L, 100000),
    is_list(L),
    assert(done).

test_term :-
    current_prolog_flag(pid, PID),
    kill(PID, term),
    thread_wait(done, [timeout(1)]).

:- end_tests(signals).

:- else.

test_signals.

:- endif.
