:- module(test_syntax,
          [ test_syntax/0
          ]).
:- use_module(library(plunit)).

test_syntax :-
    run_tests([ syntax,
                iso_op_table_6
              ]).

:- meta_predicate
    term_string_(-, :).

term_string_(Term, M:String) :-
    term_string(Term, String, [module(M)]).

:- begin_tests(syntax).

:- op(600, fx, fx600).
:- op(600, fy, fy600).
:- op(500, xf, xf500).
:- op(100, yf, af).

test(op_1) :-
    term_string(+(3,*(4,5)), "3+4*5").
test(op_2) :-
    term_string(+(+(1,2),3), "1+2+3").
test(op_3, error(syntax_error(operator_clash))) :-
    term_string(_, "a:-b:-c").
test(op_4) :-
    context_module(M),
    term_string(fx600(+(1,2)), "fx600 1+2", [module(M)]).
test(op_5, error(syntax_error(operator_clash))) :-
    context_module(M),
    term_string(_, "fx600 fx600 1", [module(M)]).
test(op_6) :-
    context_module(M),
    term_string(fy600(fy600(1)), "fy600 fy600 1", [module(M)]).
test(op_7) :-
    context_module(M),
    term_string(fy600(xf500(a)), "fy600 a xf500", [module(M)]).
test(op_8) :-                         % assume 200 fy and 500 yfx
    term_string(-(-(a)), "- - a").
test(atom_1) :-
    atom_codes('\003\\'\n\x80\', X),
    X == [3, 39, 10, 128].
test(char_1) :-
    10 == 0'\n.
test(char_2) :-
    52 == 0'\x34.
test(char_3) :-
    "\\" =:= 0'\\.
test(char_4) :-
    1-48 == 1-0'0.
test(cannot_start_term_1, error(syntax_error(cannot_start_term))) :-
    term_string(_, "p(]").

test(string_1) :-
    '\c ' == ''.
test(string_2) :-
    'x\c y' == xy.
test(quote_1, error(syntax_error(undefined_char_escape(x)))) :-
    term_string(_, '\'\\x\'').
test(quote_2) :-
    '\x61' == a.
test(quote_3) :-
    '\x61\' == a.
test(quote_4) :-
    char_code('\'', 39).
test(quote_5) :-
    0'\' == 0''.
test(quote_6) :-
    0'\' == 0'''.
test(quote_7, T == '') :-
    term_string(T, '\'\\\n\'').
test(base_1) :-
    1+1 == 1+1.
test(base_2) :-
    16'af == 175.
test(base_3) :-
    10 af == af(10).
test(base_4) :-
    A = 1, B is A+1, B == 2.
test(base_5) :-
    A is 1.0e+0+1, A == 2.0.
test(number_2, error(syntax_error(end_of_file))) :-
    term_string(_, '2\'').
test(neg_base, N == -47) :-
    term_string(N, "-16'2f").
test(zero_1) :-
    term_string(T, 'hello("\000\x")'),
    T = hello(A0),
    (   A0 == [0,120]               % depending on the double quotes flag
    ;   string_codes(A0, [0,120])
    ;   A0 == ['\u0000', x]
    ),
    !.
test(latin_1) :-
    atom_codes(A, [247]),
    term_string(T, A),
    atom_codes(T, [247]).

:- end_tests(syntax).

:- begin_tests(iso_op_table_6).

:- op(100, fy,  fy).
:- op(100, xfy, xfy).
:- op(100, yfx, yfx).
:- op(100, yf,  yf).

test(r1, T == fy(fy(1))) :-
    term_string_(T, "fy fy 1").
test(r2, T == xfy(1, xfy(2,3))) :-
    term_string_(T, "1 xfy 2 xfy 3").
test(r3, T == xfy(1, yfx(2,3))) :-
    term_string_(T, "1 xfy 2 yfx 3").
test(r4, T == fy(yf(2))) :-
    term_string_(T, "fy 2 yf").
test(r5, T == yf(yf(1))) :-
    term_string_(T, "1 yf yf").
test(r6, T == yfx(yfx(1,2),3)) :-
    term_string_(T, "1 yfx 2 yfx 3").

:- end_tests(iso_op_table_6).

