:- module(test_undo,
          [ test_undo/0
          ]).
:- use_module(library(plunit)).

test_undo :-
    run_tests([ undo
              ]).

:- begin_tests(undo).

:- dynamic a/1.

test(undo_or) :-
    (   assert(a(1), Ref),
        undo(erase(Ref)),
        fail
    ;   \+ a(1)
    ).
test(clauses) :-
    t1.
test(error, throws(x)) :-
    (   undo(throw(x)),
        fail
    ;   ok                              % true is a VMI
    ).
test(error2) :-
    catch((assert(a(3), Ref),
           undo(erase(Ref)),
           throw(x)),
          x,
          true),
    \+ a(3).
test(cleanup, fail) :-                 % issue #1414
    \+ \+ once((undo(true), fail)).

ok.

t1 :-
    assert(a(1), Ref),
    undo(erase(Ref)),
    fail.
t1 :-
    \+ a(1).

:- end_tests(undo).
