:- module(test_module, [test_module/0]).
:- use_module(library(plunit)).

/** <module> Test Prolog module handling

This module is a Unit test for Prolog module oddities.

@author	Jan Wielemaker
*/

test_module :-
	run_tests([ module
		  ]).

% test resetting the context module after a clause that uses
% I_CONTEXT

:- multifile
        cross/1.

test_module_2:(test_module:cross(_) :- nono).
test_module_2:(nono :- fail).

cross(M) :-
        context_module(M).

t(X) :-
	test_module:(true->X=1;X=2).

:- begin_tests(module).

test(cross, X == test_module) :-
	cross(X).

test(clause, H == test_module_2:term) :-
	assert(test_module_2:term, Ref),
	clause(H,_,Ref),
	erase(Ref).

test(clause, H == term) :-
	assert(test_module_2:term, Ref),
	test_module_2:clause(H,_,Ref),
	erase(Ref).

test(clause, H == term) :-
	assert(test_module_2:term, Ref),
	clause(test_module_2:H,_,Ref),
	erase(Ref).

test(qcontrol, all(X==[1])) :-
	t(X).

test(mqual, [sto(rational_trees),
	     error(type_error(acyclic_term, T))]) :-
	T = a:T,
	strip_module(T, _M, _P).

:- meta_predicate mqual(:).
mqual(_).

test(mqual, [sto(rational_trees),
	     error(type_error(acyclic_term, T))]) :-
	T = a:T,
	mqual(T).

:- end_tests(module).
