:- module(test_dcg_high_order, [test_dcg_high_order/0]).
:- use_module(library(dcg/high_order)).

test_dcg_high_order :-
    run_tests([sequence]).

:- begin_tests(sequence).

a(a) --> "a".

b(b1) --> "b".
b(b2) --> "b".

sep --> ",".

start --> "(".

end --> ")".

:- use_module(library(dcg/basics), [string//1]).

test('sequence//2 ground list',
     forall(member(t(Codes, Result, Rest),
                   [t(``, [], []),
                    t(`x`, [], `x`),
                    t(`a`, [a], []),
                    t(`aaa`, [a,a,a], []),
                    t(`ax`, [a], `x`),
                    t(`aaax`, [a,a,a], `x`)
                   ]))
    ) :-
    phrase(sequence(a, Result), Codes, Rest).

test('sequence//2 order of solutions',
     all(List-Rest == [[a,a]-``, [a]-`a`, []-`aa`])) :-
    phrase(sequence(a, List), `aa`, Rest).

test('sequence//2 det element',
     [forall(member(t(Codes, Result, Rest),
                    [t(`a`, [a], []),
                     t(`x`, [], `x`),
                     t(`ax`, [a], `x`),
                     t(`aaa`, [a,a,a], ``),
                     t(`aaax`, [a,a,a], `x`)
                    ])),
      nondet
     ]) :-
    phrase(sequence(a, L), Codes, R),
    L == Result,
    R == Rest.

test('sequence//2 nondet element', all(B == [b1,b2])) :-
    phrase(sequence(b, [B,B]), `bb`, ``).
test('sequence//2 nondet element and rest', all(B == [b1,b2])) :-
    phrase(sequence(b, [B,B]), `bbx`, `x`).

test('sequence//3 det element',
     [forall(member(t(Codes, Result, Rest),
                    [t(``, [], []),
                     t(`a`, [a], []),
                     t(`x`, [], `x`),
                     t(`ax`, [a], `x`),
                     t(`a,a,a`, [a,a,a], ``),
                     t(`a,a,ax`, [a,a,a], `x`)
                    ])),
      nondet
     ]) :-
    phrase(sequence(a, sep, L), Codes, R),
    L == Result,
    R == Rest.

test('sequence//3 det element trailing sep', fail) :-
    phrase(sequence(a, sep, L), `a,`, R),
    L == [a],
    R == `,`.

test('sequence//3 det element trailing sep consumed silently', fail) :-
    phrase(sequence(a, sep, L), `a,`, R),
    L == [a],
    R == [].

test('sequence//3 separator only', fail) :-
    phrase(sequence(a, sep, _L), `,`).

test('sequence//3 nondet element', nondet) :-
    phrase(sequence(string, sep, L), `b,b`, R),
    L == [`b`, `b`],
    R == [].

test('sequence//5 det element',
     [forall(member(t(Codes, Result, Rest),
             [t(`()`, [], []),
              t(`(a)`, [a], []),
              t(`(a,a)`, [a,a], []),
              t(`()x`, [], `x`),
              t(`(a,a)x`, [a,a], `x`)
             ]))
     ]) :-
    phrase(sequence(start, a, sep, end, L), Codes, R),
    L == Result,
    R == Rest.

test('sequence//5 det element trailing sep', fail) :-
    phrase(sequence(start, a, sep, end, _L), `(a,)`, _R).

test('sequence//5 sep only', fail) :-
    phrase(sequence(start, a, sep, end, _L), `(,)`, _R).

test('sequence//5 nondet element') :-
    phrase(sequence(start, string, sep, end, L), `(b,b)`, R),
    L == [`b`, `b`],
    R == [].

:- end_tests(sequence).
%--------------------------------------------------------- 87 library/test_error
:- module(test_error, [test_error/0]).
:- use_module(library(plunit)).

test_error :-
	run_tests([ must_be ]).

:- begin_tests(must_be, []).
:- use_module(library(error)).

test(integer, []) :-
	1 = Culprit, must_be(integer,Culprit).
test(integer, [error(instantiation_error)]) :-
	_ = Culprit, must_be(integer, Culprit).
test(integer, [error(instantiation_error)]) :-
	_ = Culprit, must_be(Culprit, integer).
test(integer, [error(type_error(integer,Culprit))]) :-
	x = Culprit, must_be(integer, Culprit).
test(integer, [error(type_error(integer,Culprit))]) :-
	[_] = Culprit, must_be(integer, Culprit).
test(rational, [error(instantiation_error)]) :-
	a(_) = Culprit, must_be(rational,Culprit).
test(rational, []) :-
	1 = Culprit, must_be(rational,Culprit).
test(rational, [error(type_error(rational,Culprit))]) :-
	a = Culprit, must_be(rational,Culprit).
test(rational, [error(type_error(rational,rdiv(x,2)))]) :-
	rdiv(x,2) = Culprit, must_be(rational,Culprit).
test(rational, [error(instantiation_error)]) :-
	rdiv(_,2) = Culprit, must_be(rational,Culprit).
test(list_of_integer, [error(instantiation_error)]) :-
	_ = Culprit, must_be(list(integer), Culprit).
test(list_of_integer, [error(instantiation_error)]) :-
	[_] = Culprit, must_be(list(integer), Culprit).
test(list_of_integer, [error(instantiation_error)]) :-
	[1,_] = Culprit, must_be(list(integer), Culprit).
test(list_of_integer, [error(type_error(integer,x))]) :-  % per analogiam 8.16.4.3 d
	[x] = Culprit, must_be(list(integer), Culprit).
test(list_of_integer, [error(instantiation_error)]) :-  % per analogiam 8.16.4.3 a
	[x|_] = Culprit, must_be(list(integer), Culprit).
test(list_of_integer, [sto(rational_trees),error(type_error(list(integer), Culprit))]) :-
	[1|Culprit] = Culprit, must_be(list(integer),Culprit).
test(list_of_integer, [error(type_error(list(integer), Culprit))]) :-
	[1|x] = Culprit, must_be(list(integer),Culprit).
test(list_of_integer, [error(type_error(list(integer), Culprit))]) :-
	[1|s(_)] = Culprit, must_be(list(integer),Culprit).

:- end_tests(must_be).
