:- module(test_lazy_lists,
	  [ test_lazy_lists/0
	  ]).
:- use_module(library(lazy_lists)).
:- use_module(library(plunit)).
:- use_module(library(dcg/basics)).

test_lazy_lists :-
	run_tests([ lazy_lists
		  ]).

:- begin_tests(lazy_lists).

test(list, Rest == `world`) :-
	setup_call_cleanup(
	    ( open_string("hello world", In),
	      lazy_list(lazy_get_codes(In, 1), List)
	    ),
	    phrase(("hello", " ", string(Rest)), List),
	    close(In)),
	!.

% Verify that the Next argument is not copied

test(state, Final == 5) :-
    State = x(1, 5),
    lazy_list(next(State), List),
    forall(member(_, List),
           true),
    arg(1, State, Final).

next(State, List, Tail) :-
    State = x(Here, Max),
    (   Here < Max
    ->  Here2 is Here+1,
        List = [Here2|Tail],
        nb_setarg(1, State, Here2)
    ;   List = [],
        Tail = []
    ).

:- end_tests(lazy_lists).
