/** <module> Test source-information on clauses

This  module  tests  clause_info/4,  a  vital  part  of  the  SWI-Prolog
source-level debugger.
*/

%t :-
%	debug(clause_info),
%	test_prolog_clause.

test_prolog_clause :-
	run_tests([ prolog_clause
		  ]).

:- begin_tests(prolog_clause).

:- style_check(-no_effect).
:- '$clausable'((t0/0,t1/0,t2/0,t3/0,t4/0,t5/0,t6/0)).
t0 :-	a(X), b(Y), X=Y.
t1 :-	a, _ = hello, b.
t2 :-	a(X), a(b) = X, b(X).
t3 :-	a, _ == hello, b.
t4 :-	a(X), x == X, b(X).
t5 :-	a(X), f(x) = X, b(X).
t6 :-	i(A), B is A-1, b(B).
:- style_check(+no_effect).

a.
b.
a(_).
b(_).
i(10).

test_ci(Head) :-
	clause(Head, _Body, Ref),
	clause_info(Ref, File, _TermPos, _NameOffset),
	atom(File).

test(t0) :- test_ci(t0).
test(t1) :- test_ci(t1).
test(t2) :- test_ci(t2).
test(t3) :- test_ci(t3).
test(t4) :- test_ci(t4).
test(t5) :- test_ci(t5).
test(t6) :- test_ci(t6).

:- end_tests(prolog_clause).
