test(lookup1, Result == [1,2,3,[a-1,b-2,c-3]]) :-
    list_to_rbtree([a-1,b-2,c-3], Tree),
    rb_visit(Tree, TreeList),
    rb_lookup(a, ValA, Tree),
    rb_lookup(b, ValB, Tree),
    rb_lookup(c, ValC, Tree),
    Result = [ValA,ValB,ValC,TreeList].
