    rb_visit(Tree4, Tree4List),
    rb_min(Tree4, Min, MinVal),
    rb_max(Tree4, Max, MaxVal),
    Result = [Size1,Size2,Size3,Size4,Min-MinVal,Max-MaxVal,Tree4List].

