test(steadfast_rb_visit) :-
    list_to_rbtree([a-1,b-2], Tree),
    rb_visit(Tree, [a-1,b-2]).
test(steadfast_empty_1a) :-
    rb_empty(Empty),
    rb_empty(Empty). % make sure rb_empty/1 allows an existing tree
test(steadfast_empty_1b) :-
    list_to_rbtree([], Empty),
    rb_empty(Empty).
