test(lt) :-
    cmp_versions(<, '9.1.1-23-g955d063c0', '9.1.2').
test(lt) :-
    cmp_versions(<, '9.1.2-22-g955d063ca', '9.1.2-23-g955d063c0').

:- end_tests(cmp_versions).

