          ]).
:- use_module(library(plunit)).
:- use_module(library(when)).

test_when :-
    run_tests([ when
              ]).

:- begin_tests(when).

% From PR832 by @dgelessus

test(nested_ground, Frozen =@= Constraint) :-
    Constraint = when(ground(A) ; ((ground(B), ground(C))),
                      plunit_when:whened(Whened)),
    call(Constraint),
    Term = A+B+C+Whened,
    copy_term(Term, Term, [Frozen]).
test(nested_ground, Frozen =@= Constraint) :-
    Constraint = when(ground(A) ; ((ground(B), ground(C)), ground(D)),
                      plunit_when:whened(Whened)),
    call(Constraint),
    Term = A+B+C+D+Whened,
    copy_term(Term, Term, [Frozen]).
test(nested_ground, Frozen =@= Constraint) :-
    Constraint = when(ground(A) ; (((ground(B),ground(C)),ground(D)), ground(E)),
                      plunit_when:whened(Whened)),
    call(Constraint),
    Term = A+B+C+D+E+Whened,
    copy_term(Term, Term, [Frozen]).

whened(true).

:- end_tests(when).
